package com.watchreader.fanqie;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.BooleanSupplier;
import org.json.*;
import static com.watchreader.fanqie.ReaderPlugin.*;

/** Concurrent fetches, ordered writes, durable gaps/cancellation, UI settings and live IPC. */
public final class ParallelDownloadInstrumentation extends Instrumentation {
    JSONArray checks=new JSONArray(),failures=new JSONArray();String stage="start";int liveRead;File fixture;FanqieActivity activity;
    void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks.put(name);}
    void main(Runnable r){runOnMainSync(r);waitForIdleSync();}
    <T extends View>T find(View root,Class<T> type,String label){if(type.isInstance(root)&&(label==null||(root instanceof TextView&&((TextView)root).getText().toString().equals(label))))return type.cast(root);if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++){T v=find(g.getChildAt(i),type,label);if(v!=null)return v;}}return null;}
    View decor(){return activity.getWindow().getDecorView();}
    void await(BooleanSupplier condition)throws Exception{long deadline=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<deadline){boolean[] ok={false};main(()->ok[0]=condition.getAsBoolean());if(ok[0])return;Thread.sleep(100);}throw new IOException("Timeout at "+stage);}
    void button(String label)throws Exception{await(()->find(decor(),Button.class,label)!=null);}
    void click(String label){main(()->{Button b=find(decor(),Button.class,label);if(b==null)throw new AssertionError("Missing "+label);b.performClick();});}
    File folder(String name){return new File(fixture,name);}
    JSONObject state(File work)throws Exception{File file=work.listFiles((d,n)->n.endsWith(".json"))[0];return new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));}
    void ordered(File file,Mock mock)throws Exception{String text=new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);int previous=-1;for(ChapterInfo c:mock.list){int at=text.indexOf(c.title);check("ordered-once:"+file.getParentFile().getName()+":"+c.id,at>previous&&at==text.lastIndexOf(c.title));previous=at;}}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    @Override public void onStart(){android.content.SharedPreferences prefs=getTargetContext().getSharedPreferences("watchreader",0);boolean had=prefs.contains("downloadThreads");int old=prefs.getInt("downloadThreads",3);ExecutorService coordinator=Executors.newSingleThreadExecutor();try{
        Context ctx=getTargetContext();activity=(FanqieActivity)startActivitySync(new Intent(ctx,FanqieActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("progress_test_readonly",true));button("书架分类");fixture=new File(ctx.getFilesDir(),"parallel-download-tests-"+System.currentTimeMillis());fixture.mkdirs();BookInfo book=new BookInfo("9918833","多线程下载测试","");
        for(int threads=1;threads<=4;threads++){stage="parallelism-"+threads;Mock mock=new Mock(7,threads);File books=folder("books-"+threads),work=folder("work-"+threads);AtomicBoolean bounded=new AtomicBoolean();File file=new LocalBookDownloader(books,work,threads).download("test",book,mock.list,mock,()->false,(done,total)->{if(done==1)bounded.set(mock.calls.get()==mock.barrierSize);});check("real-overlap-at-"+threads+"-workers",mock.peak.get()==threads);check("bounded-window-at-"+threads+"-workers",bounded.get());ordered(file,mock);if(threads>1)check("out-of-order-replies-are-reordered-"+threads,!mock.completed.get(0).equals(mock.list.get(0).id));}
        stage="pause-and-resume";Mock paused=new Mock(6,3);AtomicBoolean cancel=new AtomicBoolean();File pBooks=folder("paused-books"),pWork=folder("paused-work");File partial=new LocalBookDownloader(pBooks,pWork).download("test",book,paused.list,paused,cancel::get,(done,total)->{if(done==2)cancel.set(true);});check("pause-keeps-contiguous-checkpoint",partial==null&&state(pWork).getInt("done")==2&&pBooks.listFiles().length==0);int first=paused.count(paused.list.get(0).id),second=paused.count(paused.list.get(1).id);paused.barrier=null;cancel.set(false);File resumed=new LocalBookDownloader(pBooks,pWork).download("test",book,paused.list,paused,()->false,(d,t)->{});check("resume-does-not-refetch-committed-chapters",paused.count(paused.list.get(0).id)==first&&paused.count(paused.list.get(1).id)==second);ordered(resumed,paused);
        stage="failed-gap";Mock gap=new Mock(6,3);gap.fail=2;File gBooks=folder("gap-books"),gWork=folder("gap-work");try{new LocalBookDownloader(gBooks,gWork).download("test",book,gap.list,gap,()->false,(d,t)->{});throw new AssertionError("Failure was ignored");}catch(IOException expected){}check("failed-chapter-prevents-publishing-and-skipping",gBooks.listFiles().length==0&&state(gWork).getInt("done")==2);int known=gap.count(gap.list.get(0).id);gap.fail=-1;gap.barrier=null;File retry=new LocalBookDownloader(gBooks,gWork).download("test",book,gap.list,gap,()->false,(d,t)->{});check("failure-retry-preserves-earlier-chapters",gap.count(gap.list.get(0).id)==known);ordered(retry,gap);
        stage="cancel-slow-request";Mock slow=new Mock(6,3);slow.delay=3000;AtomicBoolean stop=new AtomicBoolean();Future<File> pending=coordinator.submit(()->new LocalBookDownloader(folder("slow-books"),folder("slow-work")).download("test",book,slow.list,slow,stop::get,(d,t)->{}));if(!slow.started.await(5,TimeUnit.SECONDS))throw new IOException("Workers did not start");long at=SystemClock.uptimeMillis();stop.set(true);check("pause-does-not-wait-for-network-timeout",pending.get(2,TimeUnit.SECONDS)==null&&SystemClock.uptimeMillis()-at<1500);
        stage="thread-choice-ui";Mock ui=new Mock(5,3);BookInfo uiBook=new BookInfo("99188339","并发下载自动化测试","");main(()->{prefs.edit().putInt("downloadThreads",2).commit();activity.plugin=ui;activity.downloadPage(uiBook);});button("下载线程：2（点击切换）");click("下载线程：2（点击切换）");check("thread-choice-is-persisted",prefs.getInt("downloadThreads",0)==3);click("开始 / 继续下载");button("离线阅读");check("download-ui-uses-selected-parallelism",ui.peak.get()==3);File uiFile=new File(ctx.getFilesDir(),"books/并发下载自动化测试_99188339.txt");check("parallel-ui-download-publishes-local-txt",uiFile.isFile()&&uiFile.delete());
        stage="live-parallel-plugin";RemotePluginClient real=new RemotePluginClient(ctx);try{real.refresh();List<ChapterInfo> list=real.directory("7134994653631220774");List<Future<ChapterContent>> reads=new ArrayList<>();ExecutorService network=Executors.newFixedThreadPool(3);try{for(int i=0;i<3;i++){ChapterInfo c=list.get(i);reads.add(network.submit(()->real.chapter("7134994653631220774",c)));}for(int i=0;i<3;i++){ChapterContent chapter=reads.get(i).get(100,TimeUnit.SECONDS);check("live-concurrent-chapter-decrypts-"+i,chapter.itemId.equals(list.get(i).id)&&!chapter.paragraphs.isEmpty()&&!chapter.version.isEmpty());liveRead++;}}finally{network.shutdownNow();}}finally{real.close();}
        main(()->{activity.plugin=new Mock(3,0);activity.home();});button("书架分类");
    }catch(Throwable e){failures.put(stage+": "+e.getClass().getSimpleName()+" "+e.getMessage());}finally{coordinator.shutdownNow();android.content.SharedPreferences.Editor edit=prefs.edit();if(had)edit.putInt("downloadThreads",old);else edit.remove("downloadThreads");edit.commit();try{JSONObject report=new JSONObject().put("checks",checks).put("failures",failures).put("live_chapters_read",liveRead).put("real_public_posts",0).put("real_cloud_test_position_writes",0);try(FileOutputStream output=new FileOutputStream(new File(getTargetContext().getFilesDir(),"parallel-download-report.json"))){output.write(report.toString(2).getBytes(StandardCharsets.UTF_8));}Bundle result=new Bundle();result.putString("summary","parallel checks="+checks.length()+" failures="+failures.length());result.putString("failures",failures.toString());finish(failures.length()==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}catch(Exception ignored){finish(0,new Bundle());}}}
    static final class Mock implements ReaderPlugin {
        final List<ChapterInfo> list=new ArrayList<>();final AtomicInteger active=new AtomicInteger(),peak=new AtomicInteger(),calls=new AtomicInteger();final ConcurrentMap<String,AtomicInteger> counts=new ConcurrentHashMap<>();final List<String> completed=Collections.synchronizedList(new ArrayList<>());final int barrierSize;volatile CyclicBarrier barrier;volatile int fail=-1;volatile long delay;final CountDownLatch started;
        Mock(int n,int threads){barrierSize=threads;started=new CountDownLatch(Math.max(1,threads));if(threads>1)barrier=new CyclicBarrier(threads);for(int i=0;i<n;i++)list.add(new ChapterInfo("9918833"+i,"第"+(i+1)+"章 [并发标记"+i+"]","v"));}
        int count(String id){AtomicInteger n=counts.get(id);return n==null?0:n.get();}
        public String id(){return "mock";}public Page<BookInfo> bookshelf(String c){return new Page<>(Collections.singletonList(new BookInfo("9918833","测试书","")),"",false);}public Page<BookInfo> search(String q,String c){return bookshelf(c);}public List<ChapterInfo> directory(String book){return list;}
        public ChapterContent chapter(String book,ChapterInfo chapter)throws Exception{int index=list.indexOf(chapter);calls.incrementAndGet();counts.computeIfAbsent(chapter.id,k->new AtomicInteger()).incrementAndGet();int n=active.incrementAndGet();peak.accumulateAndGet(n,Math::max);started.countDown();try{CyclicBarrier gate=barrier;if(gate!=null&&index<barrierSize)gate.await(5,TimeUnit.SECONDS);Thread.sleep(delay>0?delay:index==0?180:15);if(index==fail)throw new IOException("下载模拟章节失败");completed.add(chapter.id);return new ChapterContent(book,chapter.id,chapter.title,"v",Collections.singletonList(new Paragraph(0,"正文内容"+index)));}finally{active.decrementAndGet();}}
        public Page<Comment> comments(ChapterContent c,Paragraph p,String next){return new Page<>(Collections.emptyList(),"",false);}public String publish(ChapterContent c,Paragraph p,String text){throw new AssertionError("No test posts");}
    }
}
